// tcgen05 mma_k width along K-dim

int MMA_K_BYTES = 32; // in bytes

int MMA_K = 16; // in BF16 values



// for now, think of each K-major SMEM "descriptor" as a

// pointer-like value selecting current micro-tile

// (it also contains some layout metadata, covered later)

uint64_t q_desc = noswizzle::desc_kmajor(Q_smem, BLOCK_M);

uint64_t k_desc = noswizzle::desc_kmajor(K_smem, BLOCK_N);



// offsets to advance the descriptors to next Q and K micro-tiles

// (minor detail, divide by 16 because descriptor addresses are encoded in 16B units)

uint64_t q_desc_step = (BLOCK_M * MMA_K_BYTES) / 16;

uint64_t k_desc_step = (BLOCK_N * MMA_K_BYTES) / 16;



// BLOCK_K= HEAD_DIM = 128, MMA_K=16, so 8 micro-steps

for (int k = 0; k < HEAD_DIM / MMA_K; ++k) {



    // one micro-step

    tcgen05::mma_f16(

        taddr_s, q_desc, k_desc,

        /*MMA shape and dtypes=*/i_desc_qk,

        /*enable_input_d=*/(k == 0 ? 0 : 1));



    // advance descriptors to the next pair of micro-tiles

    q_desc += q_desc_step;

    k_desc += k_desc_step;

}



// make mbarrier track completion of all 8 micro-steps

tcgen05::commit_arrive(mbar_addr);

// Section A, covered earlier

