// rescale old state to the new basis

rescale     = exp(running_rowmax - new_rowmax);

running_rowsum *= rescale;

O              *= rescale;



// produce P and update denom

P               = exp(S - new_rowmax);

running_rowsum  += row_sum(P);

running_rowmax   = new_rowmax;



